gnizing Assets, Liabilities, and Consideration", "children": [{"id": "2fc1a6ab-31ed-48e6-b944-0fa705d08551", "type": "concept", "title": "Identifiable net assets"}, {"id": "d9aebda9-a999-4a57-b015-776c9887824a", "type": "concept", "title": "Contingent consideration"}, {"id": "456e2e8b-34ea-45ea-9865-f57fdf289b85", "type": "concept", "title": "Acquisition-related costs"}, {"id": "542b4612-c122-4851-9868-386d0025e1e5", "type": "concept", "title": "Deferred tax effects"}, {"id": "5221805a-79c4-409f-8a33-06e3ab5432dc", "type": "concept", "title": "Indemnification assets"}], "description": "This covers fair value measurement at acquisition and what enters the opening consolidation model."}, {"id": "41031060-8908-40b6-a4a3-6007708c8121", "type": "subtopic", "title": "Goodwill and Bargain Purchase", "children": [{"id": "2bbd4608-dd72-4b95-8f68-a879d93e5f5d", "type": "concept", "title": "Goodwill calculation"}, {"id": "63453417-84f4-4abb-b21b-1c8250fc7102", "type": "concept", "title": "Bargain purchase gain"}, {"id": "fb5c1e44-7b1e-4bf9-befc-b6f0eac3e63d", "type": "concept", "title": "Noncontrolling interest measurement"}, {"id": "0df09c1a-6901-4d22-9492-421f9094086e", "type": "concept", "title": "Partial goodwill concept"}, {"id": "6b48249a-072f-4f5d-bb69-dc2bdaf0836b", "type": "concept", "title": "Purchase price allocation"}], "description": "Students learn how excess purchase price or favorable purchase terms are reported."}]}, {"id": "f6dd3c52-c9db-431c-b63e-c384436f62e0", "type": "topic", "title": "Consolidation Fundamentals and Eliminating Entries", "description": "Builds the mechanics of parent-subsidiary consolidation worksheets and group reporting.", "children": [{"id": "5a81294d-5e9a-4eb7-b2ff-e7e51543b511", "type": "subtopic", "title": "Parent-Subsidiary Worksheet Logic", "children": [{"id": "fbc0dad1-84c1-41ee-b189-ac32922e29dc", "type": "concept", "title": "Consolidation worksheet"}, {"id": "bc042a3e-c2b6-43f1-a9de-2bde37aefccb", "type": "concept", "title": "Investment in subsidiary"}, {"id": "f464db94-6375-4ad1-8509-d08af8005eff", "type": "concept", "title": "Subsidiary equity elimination"}, {"id": "32eb3121-89c1-4901-90a7-4cbe523609fc", "type": "concept", "title": "Worksheet-only entries"}, {"id": "d16103fe-62db-4ac9-9475-3501d61f6cfe", "type": "concept", "title": "Consolidated trial balance"}], "description": "Students build consolidated statements by combining accounts and eliminating investment relationships."}, {"id": "930feb60-257f-46e8-a464-f3772823a15f", "type": "subtopic", "title": "Acquisition-Date Consolidation", "children": [{"id": "43ead13c-d492-4f33-bc84-265bbb7a7144", "type": "concept", "title": "Fair value adjustments"}, {"id": "a8dcdcc6-7467-4ada-94a8-fa712cec93e2", "type": "concept", "title": "Book value versus fair value"}, {"id": "3953a9d2-0dfa-413b-8c95-c7f72b867cae", "type": "concept", "title": "Goodwill recognition"}, {"id": "89e65950-b51b-419b-b99a-77076ba36363", "type": "concept", "title": "Elimination entry S"}, {"id": "61100b44-69b4-4cd4-bb99-c7c1fcf1c3d4", "type": "concept", "title": "Elimination entry A"}], "description": "This introduces the first consolidation point before post-acquisition activity complicates the model."}, {"id": "e05b06bc-6feb-4174-9a69-2c6f92b933ad", "type": "subtopic", "title": "Post-Acquisition Consolidation", "children": [{"id": "43f07acf-6aac-4ccf-bc07-9dc358008a7b", "type": "concept", "title": "Equity method adjustment"}, {"id": "ff026652-9a2e-4c94-a82c-698f03eb3979", "type": "concept", "title": "Amortization of fair value differentials"}, {"id": "7b1d2db1-bc5a-45fd-b06a-d525d262288a", "type": "concept", "title": "Elimination entry I"}, {"id": "64ce9b73-9674-4dad-989b-122af6cabee3", "type": "concept", "title": "Elimination entry D"}, {"id": "718500b8-ff97-496a-b19a-e56afc045dff", "type": "concept", "title": "Consolidated retained earnings"}], "description": "Students track subsidiary income, dividends, and amortization after acquisition."}]}, {"id": "54cfb381-0134-4